    public Event(
            int command,
            int target,
            int flags,
            float x,
            float y,
            float value,
            String text,
            int b,
            int c) {
        this.command = command;
        this.target = target;
        this.flags = flags;
        this.x = x;
        this.y = y;
        this.value = value;
        this.text = text;
        this.b = b;
        this.c = c;
    }

    public int command() {
        return command;
    }

    public int target() {
        return target;
    }

    public int flags() {
        return flags;
    }

    public float x() {
        return x;
    }

    public float y() {
        return y;
    }

    public float value() {
        return value;
    }

    public String text() {
        return text;
    }

    public int b() {
        return b;
    }

    public int c() {
        return c;
    }

    public int getCommand() {
        return command;
    }

    public int getTarget() {
        return target;
    }

    public int getFlags() {
        return flags;
    }

    public float getX() {
        return x;
    }

    public float getY() {
